SELECT CASE WHEN c.credit_limit >= 16000 THEN 'high' WHEN c.credit_limit >= 4500 THEN 'mid' ELSE 'low' END credit_limit_bucket, MONTH(c.signup_date) signup_month, COUNT(DISTINCT we.duration_sec) unique_event_types FROM web_events we INNER JOIN sessions s ON s.id = we.session_id FULL OUTER JOIN customers c ON s.customer_id = c.id WHERE s.device = 'desktop' GROUP BY CASE WHEN c.credit_limit >= 16000 THEN 'high' WHEN c.credit_limit >= 4500 THEN 'mid' ELSE 'low' END, MONTH(c.signup_date) ORDER BY credit_limit_bucket;
